package com.financialfraudassistant.model;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import java.time.LocalDateTime;
@Entity @Table(name="financial_goals", indexes=@Index(name="idx_goal_user", columnList="user_id"))
public class FinancialGoal { public enum Status{ACTIVE,COMPLETED} @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Integer id; @Version @Column(columnDefinition = "bigint default 0") private Long version; @ManyToOne(optional=false) @JoinColumn(name="user_id") private User user; @Column(nullable=false) private String name; @Column(name="target_amount",nullable=false,precision=12,scale=2) private BigDecimal targetAmount; @Column(name="current_amount",nullable=false,precision=12,scale=2) private BigDecimal currentAmount; private LocalDate deadline; @Column(name="monthly_contribution",nullable=false,precision=12,scale=2) private BigDecimal monthlyContribution; @Enumerated(EnumType.STRING) private Status status=Status.ACTIVE; @Column(name="created_at",updatable=false) private LocalDateTime createdAt=LocalDateTime.now(); protected FinancialGoal(){} public FinancialGoal(User u,String n,BigDecimal t,BigDecimal c,LocalDate d,BigDecimal m){user=u;name=n;targetAmount=t;currentAmount=c;deadline=d;monthlyContribution=m;if(c.compareTo(t)>=0)status=Status.COMPLETED;} public void update(String n,BigDecimal t,BigDecimal c,LocalDate d,BigDecimal m){name=n;targetAmount=t;currentAmount=c;deadline=d;monthlyContribution=m;if(c!=null&&c.compareTo(t)>=0)status=Status.COMPLETED;else status=Status.ACTIVE;} public Integer getId(){return id;} public String getName(){return name;} public BigDecimal getTargetAmount(){return targetAmount;} public BigDecimal getCurrentAmount(){return currentAmount;} public LocalDate getDeadline(){return deadline;} public BigDecimal getMonthlyContribution(){return monthlyContribution;} public Status getStatus(){return status;} }
